import sys

def process_word(word):
    # Condition 1: all uppercase
    if word == word.upper():
        return word.swapcase()
    # Condition 2: first lowercase, rest uppercase
    if len(word) > 0 and word[0].islower() and (len(word) == 1 or word[1:].isupper()):
        return word.swapcase()
    return word

word = sys.stdin.readline().strip()
print(process_word(word))
"}

