n = int(input())
x = list(map(int, input().split()))
y = list(map(int, input().split()))

# Create a set of all values
all_values = set(x + y)

# Count how many pairs satisfy the condition
count = 0

for xi in x:
    for v in all_values:
        # For a given xi and value v, we need to check if xi XOR v exists in y
        target = xi ^ v
        if target in y:
            count += 1

# Determine the winner
if count % 2 == 0:
    print("Karen")
else:
    print("Koyomi")
"}

