n, m = map(int, input().split())

# Read the matrix
switches = []
for _ in range(n):
    row = input().strip()
    switches.append(row)

# Check each switch for redundancy
redundant_exists = False
for switch_idx in range(n):
    # Lamps turned on by this switch
    lamps_turned_on = set()
    for lamp_idx in range(m):
        if switches[switch_idx][lamp_idx] == '1':
            lamps_turned_on.add(lamp_idx)

    # Check if removing this switch still covers all lamps it turns on
    covers_all = True
    for lamp in lamps_turned_on:
        # Check if any other switch turns on this lamp
        covers = False
        for other_switch_idx in range(n):
            if other_switch_idx != switch_idx and switches[other_switch_idx][lamp] == '1':
                covers = True
                break
        if not covers:
            covers_all = False
            break

    if covers_all:
        redundant_exists = True
        break

print("YES" if redundant_exists else "NO")
"}

