t = int(input())
for _ in range(t):
    n = int(input())
    a = list(map(int, input().split()))

    # Check if (r + a[r]) % n are all distinct
    remainder_map = set()
    for r in range(n):
        new_remainder = (r + a[r]) % n
        if new_remainder in remainder_map:
            print("NO")
            break
        remainder_map.add(new_remainder)
    else:
        print("YES")
"}

