{"code": "
n, k = map(int, input().split())

# Initialize matrix with zeroes
matrix = [[0 for _ in range(n)] for _ in range(n)]

total_positions = n + n * (n - 1) // 2  # n diagonal positions + n*(n-1)/2 off-diagonal pairs
max_k = total_positions

if k > max_k:
    print(-1)
else:
    # Fill matrix in lexicographically maximal way
    for i in range(n):
        for j in range(i, n):
            # i is row, j is column
            if i == j:
                # Diagonal position: 1 unit
                if k >= 1:
                    matrix[i][j] = 1
                    matrix[j][i] = 1
                    k -= 1
            else:
                # Off-diagonal pair: 2 units
                if k >= 2:
                    matrix[i][j] = 1
                    matrix[j][i] = 1
                    k -= 2

            # If we've used all k, we're done
            if k == 0:
                break
        if k == 0:
            break

    # Output matrix
    for row in matrix:
        print(' '.join(map(str, row)))
"}

