from collections import Counter

s = input().strip()
freq = Counter(s)

if len(freq) == 2:
    # both must appear at least twice
    if all(v >= 2 for v in freq.values()):
        print("YES")
    else:
        print("NO")
elif len(freq) == 3:
    # at least one appears at least twice
    if any(v >= 2 for v in freq.values()):
        print("YES")
    else:
        print("NO")
else:
    # at least 4 distinct characters
    print("YES")
"}

