import sys

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)
    if n == 0:
        print(0)
        print()
        return
    # prefix sum of '[' counts
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i+1] = prefix[i] + (1 if s[i] == '[' else 0)

    stack = []  # stack of (index, char) for '(' or '['
    max_brackets = 0
    best_start = 0
    best_len = 0

    for i in range(n):
        ch = s[i]
        if ch == '(' or ch == '[':
            stack.append((i, ch))
        elif ch == ')':
            if stack and stack[-1][1] == '(':
                pos, _ = stack.pop()
                # substring from pos to i inclusive
                brackets = prefix[i+1] - prefix[pos]
                if brackets > max_brackets or (brackets == max_brackets and i - pos + 1 < best_len):
                    max_brackets = brackets
                    best_start = pos
                    best_len = i - pos + 1
        elif ch == ']':
            if stack and stack[-1][1] == '[':
                pos, _ = stack.pop()
                brackets = prefix[i+1] - prefix[pos]
                if brackets > max_brackets or (brackets == max_brackets and i - pos + 1 < best_len):
                    max_brackets = brackets
                    best_start = pos
                    best_len = i - pos + 1

    if max_brackets == 0:
        print(0)
        print()
    else:
        print(max_brackets)
        print(s[best_start:best_start+best_len])

if __name__ == "__main__":
