def is_perfect_square(x):
    """Check if x is a perfect square"""
    root = int(x**0.5)
    return root * root == x

def compute_signature(x):
    """Compute the signature of x: exponents of primes modulo 2"""
    signature = {}  # prime -> exponent modulo 2
    i = 2
    while i * i <= x:
        if x % i == 0:
            count = 0
            while x % i == 0:
                x //= i
                count += 1
            signature[i] = count % 2
        i += 1

    # If x > 1, it's a prime factor
    if x > 1:
        signature[x] = 1 % 2

    # Map to tuple for hashing
    return tuple(sorted(signature.items()))

def count_right_permutations(n, a):
    MOD = 10**9 + 7

    # DP: DP[mask][last_idx] = count
    dp = [[0] * n for _ in range(1 << n)]

    # Initialize with single numbers
    for i in range(n):
        dp[1 << i][i] = 1

    # DP transitions
    for mask in range(1, 1 << n):
        for last_idx in range(n):
            if dp[mask][last_idx] == 0:
                continue
            count = dp[mask][last_idx]

            # Try adding each number
            for i in range(n):
                if (mask & (1 << i)) == 0:  # number not used yet
                    # Check if consecutive product is perfect square
                    if not is_perfect_square(a[last_idx] * a[i]):
                        new_mask = mask | (1 << i)
                        dp[new_mask][i] = (dp[new_mask][i] + count) % MOD

    # Sum all valid permutations
    total = 0
    for i in range(n):
        total = (total + dp[(1 << n) - 1][i]) % MOD

    return total

n = int(input())
a = list(map(int, input().split()))
print(count_right_permutations(n, a))
