n = int(input())

tree = [[] for _ in range(n + 1)]
for i in range(1, n + 1):
    p, a = map(int, input().split())
    if p == -1:
        tree[1].append((i, a))
    else:
        tree[p].append((i, a))

# dp[u][0]: max efficiency when u is not selected, even number of selected children
# dp[u][1]: max efficiency when u is not selected, odd number of selected children
# dp[u][2]: max efficiency when u is selected

def dfs(u):
    # Start with state where u is not selected and we have 0 selected children (even)
    dp = [0, -1, -1]  # dp[0] = 0, dp[1] = -1, dp[2] = -1

    stack = [(u, False)]  # (node, visited)
    while stack:
        node, visited = stack.pop()

        if not visited:
            # Process children first
            stack.append((node, True))

            # Push children in reverse order
            for v, a in reversed(tree[node]):
                stack.append((v, False))
        else:
            # Now we have processed all children
            # Combine with children states
            new_dp = [-1, -1, -1]

            # For each state in current node
            for state in range(3):
                if dp[state] == -1:
                    continue

                # We need to combine with children
                for v, a in tree[node]:
                    child_dp = dfs(v)

                    # For each state in current node
                    for state_curr in range(3):
                        if dp[state_curr] == -1:
                            continue

                        # For each state in child
                        for state_child in range(3):
                            if child_dp[state_child] == -1:
                                continue

                            # If current node is not selected
                            if state_curr == 0 or state_curr == 1:
                                # The number of selected children with odd parity is state_curr
                                # Adding child with state_child changes the count
                                new_count = state_curr + (state_child == 1)

                                # If we keep current node not selected, we use the new count
                                if new_count % 2 == 0:
                                    new_dp[0] = max(new_dp[0], dp[state_curr] + child_dp[state_child])
                                else:
                                    new_dp[1] = max(new_dp[1], dp[state_curr] + child_dp[state_child])

                            # If current node is selected
                            if state_curr == 2:
                                # The number of selected children with odd parity is state_curr
                                # We need the total number of selected children with odd parity to be even
                                total_child_odd = state_child + state_curr
                                if total_child_odd % 2 == 0:
                                    new_dp[2] = max(new_dp[2], dp[state_curr] + child_dp[state_child])

            dp = new_dp

            # After processing all children, we can also consider selecting current node
            if dp[0] != -1:
                new_dp = [-1, -1, -1]
                new_dp[2] = max(new_dp[2], dp[0] + a)  # Select current node, now we have a with odd parity
                dp = new_dp

    return dp

