def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # dp_neg[i]: maximum sum of alternating subsequence ending at position i with negative last element
        # dp_pos[i]: maximum sum of alternating subsequence ending at position i with positive last element
        # dp_len[i]: maximum length of alternating subsequence ending at position i

        # We'll keep track of the best values up to each position
        dp_neg = [float('-inf')] * n
        dp_pos = [float('-inf')] * n
        dp_len = [0] * n

        for i in range(n):
            num = a[i]

            if num > 0:
                # Extend subsequences ending with negative
                if dp_neg[i-1] != float('-inf'):
                    dp_pos[i] = max(dp_neg[i-1] + num, num)
                    dp_len[i] = dp_len[i-1] + 1
                else:
                    dp_pos[i] = num
                    dp_len[i] = 1
            else:
                # Extend subsequences ending with positive
                if dp_pos[i-1] != float('-inf'):
                    dp_neg[i] = max(dp_pos[i-1] + num, num)
                    dp_len[i] = dp_len[i-1] + 1
                else:
                    dp_neg[i] = num
                    dp_len[i] = 1

        # Find the best subsequence across all positions
        best_sum = float('-inf')
        best_len = 0

        for i in range(n):
            if dp_len[i] > best_len or (dp_len[i] == best_len and dp_pos[i] > best_sum):
