        n, k, z = map(int, input().split())
        a = list(map(int, input().split()))

        # dp[x][l][0]: starting at position x (1-indexed), having made l left moves, last move not left
        # dp[x][l][1]: starting at position x, having made l left moves, last move was left
        INF = float('-inf')

        # Initialize dp
        dp = [[[-1 for _ in range(2)] for _ in range(z + 1)] for _ in range(n + 1)]
        dp[1][0][0] = a[0]  # Start at position 1, 0 left moves, last move not left

        for l in range(z + 1):
            for x in range(1, n + 1):
                if l == 0 and x == 1:
                    continue

                # From last move not left
                if dp[x][l][0] != -1:
                    # Go right
                    if x + 1 <= n:
                        dp[x + 1][l][0] = max(dp[x + 1][l][0], dp[x][l][0] + a[x])
                    # Go left
                    if l < z and x - 1 >= 1:
                        dp[x - 1][l + 1][1] = max(dp[x - 1][l + 1][1], dp[x][l][0] + a[x - 1])

                # From last move was left
                if dp[x][l][1] != -1:
                    # Can only go right
                    if x + 1 <= n:
                        dp[x + 1][l][0] = max(dp[x + 1][l][0], dp[x][l][1] + a[x])

        # Find the maximum score after k moves
        max_score = -1
        for l in range(z + 1):
            if k == 0:
                max_score = max(max_score, dp[1][0][0])
