import sys
from collections import defaultdict, deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        k = int(next(it))
        points = []

        for _ in range(n):
            x = int(next(it))
            y = int(next(it))
            points.append((x, y))

        # Build adjacency list
        adj = defaultdict(list)

        for i in range(n):
            for j in range(i + 1, n):
                dx = abs(points[i][0] - points[j][0])
                dy = abs(points[i][1] - points[j][1])
                if dx + dy <= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Find connected components using BFS
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                q = deque([i])
                visited[i] = True

                while q:
                    u = q.popleft()
                    for v in adj[u]:
                        if not visited[v]:
                            visited[v] = True
                            q.append(v)

        if components == 1:
            out_lines.append('0')
        else:
            out_lines.append('-1')

    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()
