    a = list(map(int, input().split()))

    knows = [False] * n
    knows[0] = True  # student 1 (index 0) knows initially

    sent = [0] * n  # messages sent by each student

    # Queue of students who know the news and haven't reached capacity
    queue = [0]  # BFS queue (only indexes)

    messages = []

    while queue:
        u = queue.pop(0)

        # If student u still has messages left to send
        if sent[u] < a[u]:
            # Find all students who don't know the news
            for v in range(n):
                if not knows[v] and sent[u] < a[u]:
                    # u sends to v
                    messages.append((u+1, v+1))  # convert to 1-based indexing
                    sent[u] += 1
                    knows[v] = True
                    queue.append(v)
                else:
                    # If v knows or u is full, break
                    if sent[u] >= a[u]:
