    for i in range(1, n + 1):
        if i > 1:
            left_char[i] = s[i - 2]
        else:
            left_char[i] = None

    # For each position j, what character is to the right of j (or None if j=n)
    right_char = [None] * (n + 1)
    for j in range(1, n + 1):
        if j < n:
            right_char[j] = s[j]
        else:
            right_char[j] = None

    # Count valid removals
    result = 0
    for l in range(1, n + 1):
        for r in range(l, n + 1):
            c_left = left_char[l]
            c_right = right_char[r]

            if c_left is None and c_right is None:
                # Both sides empty, we removed everything
                result += 1
            elif c_left is None:
                # Left side empty, right side has character c_right
                if c_right is None:
                    # r=n, we removed everything
                    result += 1
                else:
                    # Check if all characters from r+1 to n are equal to c_right
                    all_equal = True
                    for k in range(r, n):
                        if s[k] != c_right:
                            all_equal = False
                            break
                    if all_equal:
                        result += 1
            elif c_right is None:
                # Right side empty
                if c_left is None:
                    # l=1, both sides empty
                    result += 1
                else:
                    # Check if all characters from 1 to l-1 are equal to c_left
                    all_equal = True
                    for k in range(1, l):
                        if s[k - 1] != c_left:
                            all_equal = False
                            break
                    if all_equal:
                        result += 1
            else:
                # Both sides have characters, they must be equal
                if c_left == c_right:
                    # Check if all characters on both sides are equal to c_left (or c_right)
                    all_equal_left = True
                    for k in range(1, l):
                        if s[k - 1] != c_left:
