star_positions = [(i, j) for i in range(h) for j in range(w) if grid[i][j] == '*']

# If there are no non-empty cells, it's not a '+' shape
if not star_positions:
    print("NO")
    exit()

# Check if all non-empty cells form a single continuous cross shape
# First, find the center - a cell that has non-empty cells in all four directions
center = None
for i, j in star_positions:
    # Check if this could be the center
    is_center = True
    # Check if we're not on the edge
    if i == 0 or i == h - 1 or j == 0 or j == w - 1:
        is_center = False
    else:
        # Check if all four adjacent cells are also non-empty
        if grid[i-1][j] != '*' or grid[i+1][j] != '*' or grid[i][j-1] != '*' or grid[i][j+1] != '*':
            is_center = False

    if is_center:
        center = (i, j)
        break

if center is None:
    # No cell has non-empty cells in all four directions
    # Could be a vertical or horizontal line
    # Check if it's a vertical line
    vertical_line = [(center[0], j) for j in range(center[1], -1, -1) if (center[0], j) in star_positions]
