import math

def is_divisible_by(s, divisor):
    """Check if s is divisible by divisor"""
    # Check if s can be formed by repeating divisor x times
    if len(s) % len(divisor) != 0:
        return False
    x = len(s) // len(divisor)
    return s == divisor * x

def lcm(a, b):
    """Return least common multiple of a and b"""
    return a * b // math.gcd(a, b)

def find_lcm(s, t):
    """Find LCM of strings s and t"""
    if is_divisible_by(s, t):
        return s
    if is_divisible_by(t, s):
        return t

    # Check if LCM exists at LCM(length(s), length(t))
    l = lcm(len(s), len(t))

    # Check all possible patterns
    # If s can be repeated x times to get a pattern that works with t
    # or t can be repeated x times to get a pattern that works with s
    # or both work together

    # First check if s can form a pattern that works with t
    # s pattern: s repeated x times
    for x in range(1, l // len(s) + 1):
        candidate = s * x
        if is_divisible_by(candidate, t):
            return candidate

    # Check if t can form a pattern that works with s
    for x in range(1, l // len(t) + 1):
        candidate = t * x
        if is_divisible_by(candidate, s):
            return candidate

    return -1

q = int(input())
for _ in range(q):
    s = input().strip()
    t = input().strip()
    print(find_lcm(s, t))
