import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])

    # Calculate how many cells we can fill
    diagonal_cells = n
    off_diagonal_pairs = n * (n - 1) // 2

    total_possible = diagonal_cells + 2 * off_diagonal_pairs

    if k > total_possible:
        print(-1)
        return

    # Create matrix
    matrix = [[0 for _ in range(n)] for _ in range(n)]

    # Fill top-left triangle first
    filled = 0
    for i in range(n):
        for j in range(i, n):
            if filled >= k:
                break
            matrix[i][j] = 1
            if i != j:
                matrix[j][i] = 1
            filled += 1

    # Output matrix
    for row in matrix:
        print(' '.join(map(str, row)) + ' ')

if __name__ == '__main__':
    solve()
"}

