import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        k = int(next(it))
        z = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Initialize DP table
        # dp[pos][left_used][last_move]
        # pos: 1-indexed
        # left_used: number of left moves used
        # last_move: 0 for right, 1 for left
        # We'll use a 2D array for each state (k steps)

        # After 0 moves, we're at position 1 with 0 left moves and last move right (0)
        dp = [[[ -1 for _ in range(2)] for _ in range(z+1)] for _ in range(n+1)]
        dp[1][0][0] = a[0]  # position 1, 0 left moves, last move right

        for steps in range(k):
            new_dp = [[[ -1 for _ in range(2)] for _ in range(z+1)] for _ in range(n+1)]

            for pos in range(1, n+1):
                for left_used in range(z+1):
