import sys

def solve():
    n = int(sys.stdin.readline())
    diag1 = [0] * 2001  # i - j, range -999..999 => shift by 1000 => 0..1999
    diag2 = [0] * 2001  # i + j, range 2..2000

    for _ in range(n):
        x, y = map(int, sys.stdin.readline().split())
        offset = x - y
        diag1[offset + 1000] += 1
        diag2[x + y] += 1

    result = 0
    for count in diag1[1:2000]:  # indices 1..1999 (offset 1000 for -999..999)
        if count >= 2:
            result += count * (count - 1) // 2
    for count in diag2[2:2001]:  # indices 2..2000
        if count >= 2:
            result += count * (count - 1) // 2

    sys.stdout.write(str(result))

if __name__ == "__main__":
    solve()
"}

