import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:2+m]))

    current = 1
    total_time = 0

    for task in a:
