    """Count the number of differing digits between two times."""
    return sum(c1 != c2 for c1, c2 in zip(time1, time2))

min_changes = float('inf')
best_time = time_str

for valid_time in valid_times:
    changes = count_changes(valid_time, time_str)
    if changes < min_changes:
        min_changes = changes
        best_time = valid_time

print(best_time)
