import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return
    format_type = int(data[0])
    time_str = data[1].strip()

    # Parse original
    orig_hour_str = time_str[:2]
    orig_min_str = time_str[3:5]

    if format_type == 24:
        valid_hours = range(0, 24)
        valid_minutes = range(0, 60)
    else:  # 12-hour
        valid_hours = range(1, 13)
        valid_minutes = range(0, 60)

    min_diff = float('inf')
    best_time = None

    for h in valid_hours:
        for m in valid_minutes:
            # Format as two digits
            h_str = f"{h:02d}"
            m_str = f"{m:02d}"
            # Count differences
            diff = 0
            for i in range(2):
                if h_str[i] != orig_hour_str[i]:
                    diff += 1
            for i in range(2):
                if m_str[i] != orig_min_str[i]:
                    diff += 1

            if diff < min_diff:
                min_diff = diff
                best_time = f"{h:02d}:{m:02d}"

    print(best_time)

if __name__ == "__main__":
    solve()
"}

