import math

def lcm(a, b):
    return a * b // math.gcd(a, b)

def solve():
    q = int(input())

    for _ in range(q):
        s = input().strip()
        t = input().strip()

        len_s = len(s)
        len_t = len(t)

        # Compute LCM of the lengths
        length = lcm(len_s, len_t)

        # Check if s repeated (length/len_s) times equals t repeated (length/len_t) times
        if s * (length // len_s) == t * (length // len_t):
            print(s * (length // len_s))
        else:
            print(-1)

solve()
"}

