import sys

def f(n):
    """Sum of digits lengths from 1 to n."""
    if n < 1:
        return 0
    d = len(str(n))
    s = 0
    for i in range(1, d):
        s += 9 * 10 ** (i - 1) * i
    last_group_size = n - 10 ** (d - 1) + 1
    s += last_group_size * d
    return s

w, m, k = map(int, sys.stdin.read().split())
C = w // k

if C == 0:
    print(0)
else:
    # Binary search for max L
    low, high = 0, C
    best = 0
    while low <= high:
        mid = (low + high) // 2
        if mid == 0:
            total = 0
        else:
            total = f(m + mid - 1) - f(m - 1)
        if total <= C:
            best = mid
            low = mid + 1
        else:
            high = mid - 1
    print(best)
"}

