n, k = map(int, input().split())

# Check if it's possible to place k ones
# The maximum number of ones we can place is sum of:
# - 1 for each diagonal element (n of them)
# - 2 for each pair of symmetric elements (total of n*(n-1)/2 pairs, each can have 2 ones)
max_ones = n + 2 * (n * (n - 1) // 2)

if k > max_ones:
    print(-1)
else:
    # Create matrix of size n x n filled with 0
    matrix = [[0 for _ in range(n)] for _ in range(n)]

    i = 0
    while i < n:
        j = 0
        while j < n:
            # If we are on the diagonal, place one if we have enough
            if i == j:
                if k >= 1:
                    matrix[i][j] = 1
                    k -= 1
                j += 1
            else:
                # For symmetric positions, we need to place both (i, j) and (j, i)
                # So we need 2 ones
                if k >= 2:
                    matrix[i][j] = 1
                    matrix[j][i] = 1
                    k -= 2
                else:
                    break
                j += 1
        i += 1

    # If we still have ones left, it's impossible
    if k > 0:
        print(-1)
    else:
        for row in matrix:
            print(' '.join(map(str, row)))
