{"code": "
import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    statuses = data[1]

    count_a = 0
    count_i = 0
    count_f = 0

    for status in statuses:
        if status == 'A':
            count_a += 1
        elif status == 'I':
            count_i += 1
        else:  # 'F'
            count_f += 1

    if count_i == 0:
        result = count_a
    elif count_i == 1:
        result = 1
    else:
        result = 0

