        rows = []
        for _ in range(n):
            row = set(int(next(data)) for _ in range(m))
            rows.append(row)

        # Read m columns (each with n elements)
        cols = []
        for _ in range(m):
            col = set(int(next(data)) for _ in range(n))
            cols.append(col)

        # For each row, find which column matches it
        row_to_col = {}
        for i, row_set in enumerate(rows):
            for j, col_set in enumerate(cols):
                if len(row_set.intersection(col_set)) == 1:
                    row_to_col[i] = j
                    break

        # Now we have row_to_col mapping

        # Print the matrix
        matrix = [[0] * m for _ in range(n)]

        for i, row_set in enumerate(rows):
