def find_centroid(tree, n):
    # Find a centroid of the tree using DFS
    def dfs_size(v, parent):
        size = 1
        for u in tree[v]:
            if u != parent:
                size += dfs_size(u, v)
        return size

    def is_centroid(v):
        # Check if v is a centroid
        for u in tree[v]:
            if dfs_size(u, v) > n // 2:
                return False
        return True

    # Find the centroid starting from an arbitrary vertex
    parent = [-1] * (n + 1)
    for v in range(1, n + 1):
        if parent[v] == -1:
            # Find the centroid starting from v
            for u in range(1, n + 1):
                if u != v:
                    if dfs_size(u, -1) > n // 2:
                        parent[u] = v
                    else:
                        parent[v] = u
                        break
            # Now find the centroid
            for v_candidate in range(1, n + 1):
                if is_centroid(v_candidate):
