import sys

def parse_time(time_str):
    """Parse a time string like "05:00 a.m." into minutes since midnight."""
    # Extract hour, minute, and period
    h_str, m_str, period = time_str.split()
    h = int(h_str)
    m = int(m_str[:-2])  # Remove trailing space and period
    period = period[0]  # 'a' or 'p'

    # Convert to 24-hour format
    if period == 'a':
        if h == 12:
            h = 0  # 12 a.m. becomes 0
    else:  # 'p'
        if h < 12:
            h += 12  # 1 a.m. becomes 13, ..., 11 a.m. becomes 23
        elif h == 12:
            h = 12  # 12 p.m. stays 12

    return h * 60 + m


def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    n = int(data[0])
    times = []

    for line in data[1:n+1]:
        # Extract time from format "[time]: message"
        time_str = line.split(']:')[0][1:]  # Remove "[" and "]:
        times.append(parse_time(time_str))

    # Track current day state
    current_day_minute = None
    current_day_count = 0
    days = 1

    for minute in times:
        if current_day_minute is None:
            # First event of the day
            current_day_minute = minute
            current_day_count = 1
        elif minute > current_day_minute:
            # Later time than previous
            if current_day_count >= 10:
                days += 1
                current_day_count = 1
            else:
                current_day_count = 1
            current_day_minute = minute
        elif minute == current_day_minute:
            # Same minute as previous
