        height = s[i]

        # Calculate costs for transitions
        # From height 1 to height 1
        if height == '0':
            cost_1_1 = a + b
        else:
            cost_1_1 = float('inf')

        # From height 1 to height 2 (zig-zag)
        if height == '1':
            cost_1_2 = 2*a + 4*b
        else:
            cost_1_2 = float('inf')

        # From height 2 to height 2
        if height == '0':
            cost_2_2 = a + 2*b
        else:
            cost_2_2 = float('inf')

        # From height 2 to height 1 (zig-zag)
        if height == '1':
            cost_2_1 = 2*a + 4*b
        else:
            cost_2_1 = float('inf')

        dp = [
            min(dp[0] + cost_1_1, dp[1] + cost_2_1),
            min(dp[0] + cost_1_2, dp[1] + cost_2_2)
        ]

    results.append(dp[0])

