def solve():
    import sys
    n, k = map(int, sys.stdin.readline().split())
    matrix = [sys.stdin.readline().strip() for _ in range(n)]

    # dp[row][col][changes] = lexicographically smallest string from (row, col) with 'changes' changes left
    # We'll use a 3D array
    dp = [[['' for _ in range(k+1)] for _ in range(n)] for _ in range(n)]

    # Fill the dp table from bottom-right to top-left
    for changes in range(k+1):
        dp[n-1][n-1][changes] = matrix[n-1][n-1] if changes >= 0 else ''

    for row in range(n-1, -1, -1):
        for col in range(n-1, -1, -1):
            if row == n-1 and col == n-1:
                continue  # Already filled

            for changes in range(k+1):
                # Try moving right
                if col < n-1:
                    right_char = matrix[row][col+1]
                    new_changes = changes

                    # Can we change the right character to something smaller?
                    if changes < k and right_char > dp[row][col][changes][-1]:
                        new_changes = changes + 1
                        new_char = dp[row][col][changes][-1]
                    else:
                        new_char = right_char

                    dp[row][col][changes] = min(dp[row][col][changes], dp[row][col+1][new_changes])

                # Try moving down
                if row < n-1:
                    down_char = matrix[row+1][col]
                    new_changes = changes

                    # Can we change the down character to something smaller?
                    if changes < k and down_char > dp[row][col][changes][-1]:
                        new_changes = changes + 1
                        new_char = dp[row][col][changes][-1]
                    else:
                        new_char = down_char

                    dp[row][col][changes] = min(dp[row][col][changes], dp[row+1][col][new_changes])

    print(dp[0][0][k])

