def solve():
    n, k = map(int, input().split())

    if k == 0:
        print(-1)
        return

    result = []

    if n % 2 == 1:
        # n is odd
        if k == 1:
            # Use (n-1)/2 pairs of consecutive numbers
            for i in range(1, n):
                result.append(i)
                result.append(i + 1)
        elif k > 1:
            # Need (n-1)/2 pairs: (n-1)/2 - 1 pairs of consecutive numbers, and 1 pair with gcd = k
            base_pairs = (n - 1) // 2 - 1
            # Create base array with consecutive pairs
            for i in range(1, base_pairs * 2 + 1):
                result.append(i)
                result.append(i + 1)

            # Add the special pair with gcd = k
            # Try using (1, k)
            if 1 not in result and k not in result:
                result.append(1)
                result.append(k)
            else:
                # Adjust by using (2, 2*k) or something else
                if 1 in result:
                    result.append(2)
                if k in result:
                    result.append(2 * k)
                result.append(2)
                result.append(2 * k)

            # Add the last number
            last = n + 1
            while last in result:
                last += 1
            result.append(last)
    else:
        # n is even
        if k == n // 2:
            # Use n/2 pairs of consecutive numbers
            for i in range(1, n, 2):
                result.append(i)
                result.append(i + 1)
        else:
            print(-1)
            return

    # Verify
    total = 0
    for i in range(0, len(result) - 1, 2):
        total += math.gcd(result[i], result[i + 1])

    if total == k:
        print(' '.join(map(str, result)))
