def solve():
    n = int(sys.stdin.readline())
    stamps = []

    # Build a graph of edges
    # We'll use an adjacency list
    graph = {}

    for _ in range(n):
        a, b = map(int, sys.stdin.readline().split())

        # Add edge a -> b
        if a not in graph:
            graph[a] = []
        graph[a].append(b)

        # Add edge b -> a (if we're considering undirected edges)
        if b not in graph:
            graph[b] = []
        graph[b].append(a)

        # Record the stamp
        stamps.append((a, b))

    # Find a starting vertex (one with in-degree = 0 or out-degree = 0)
    # For Eulerian path, there should be exactly one vertex with out-degree = in-degree + 1
    # And one with in-degree = out-degree + 1
    # All others should have equal in and out degrees

    in_deg = {}
    out_deg = {}

    for a, b in stamps:
        out_deg[a] = out_deg.get(a, 0) + 1
        in_deg[b] = in_deg.get(b, 0) + 1

    # Find the start vertex
    for vertex in graph:
        if out_deg.get(vertex, 0) == in_deg.get(vertex, 0) + 1:
            start_vertex = vertex
            break
    else:
        # If not found, the start vertex has in-degree = 0 (or out-degree = 0)
        for vertex in graph:
            if in_deg.get(vertex, 0) == 0:
                start_vertex = vertex
                break

    # Build the path using a depth-first search
    path = []

    def dfs(vertex):
        while vertex in graph and graph[vertex]:
            next_vertex = graph[vertex].pop()
            dfs(next_vertex)
            path.append(vertex)

    dfs(start_vertex)

    # The path is in reverse order (last in, first out)
    path.reverse()

    # Add the start vertex at the beginning
    path = [start_vertex] + path

    print(' '.join(map(str, path)))

