def find_eulerian_path(graph, num_vertices):
    # Calculate in-degrees and out-degrees
    in_deg = [0] * (num_vertices + 1)
    out_deg = [0] * (num_vertices + 1)

    for u in range(num_vertices + 1):
        for v in graph[u]:
            out_deg[u] += 1
            in_deg[v] += 1

    # Find start vertex
    start_vertex = None
    for v in range(1, num_vertices + 1):
        if out_deg[v] == in_deg[v] + 1:
            start_vertex = v
            break

    if start_vertex is None:
        # Start with vertex with in-degree 0
        for v in range(1, num_vertices + 1):
            if in_deg[v] == 0:
                start_vertex = v
                break

    # DFS to find Eulerian path
    path = []

    def dfs(v):
        while graph[v]:
            u = graph[v].pop()
            dfs(u)
            path.append(v)

    dfs(start_vertex)

    # The path is in reverse order
    path.reverse()

