def count_substring_occurrences(s, target):
    """Count how many times `target` appears as a substring in `s`"""
    n, m = len(s), len(target)
    if m == 0 or m > n:
        return 0

    # Build failure function
    fail = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and target[i] != target[j]:
            j = fail[j-1]
        if target[i] == target[j]:
            j += 1
            fail[i] = j

    # Count occurrences
    count = 0
    j = 0
    for i in range(n):
        while j > 0 and s[i] != target[j]:
            j = fail[j-1]
        if s[i] == target[j]:
            j += 1
            if j == m:
                count += 1
                j = fail[j-1]

    return count


def solve():
    s = input().strip()
    n = len(s)

    # Find all prefixes that are also suffixes
    common_prefix_suffixes = []
    for l in range(1, n+1):
        prefix = s[:l]
        suffix = s[n-l:] if l <= n else ""
        if prefix == suffix:
            common_prefix_suffixes.append(prefix)

    # Count occurrences for each common prefix/suffix
    result = []
    for prefix in common_prefix_suffixes:
        count = count_substring_occurrences(s, prefix)
        result.append((len(prefix), count))

    # Sort by length
    result.sort()

    # Print output
    print(len(result))
    for length, count in result:
        print(length, count)

