import sys

def reflection(n):
    """Return the reflection of n."""
    return int(''.join(str(9 - int(d)) for d in str(n)))

def max_weight(l, r):
    """Return the maximum weight in the range [l, r]."""
    max_weight = 0

    # Check numbers with different digit counts
    # Start from 1-digit numbers up to the number of digits in r

    # Special case: single-digit numbers
    if r <= 9:
        for n in range(l, r + 1):
            p = reflection(n)
            weight = n * p
            if weight > max_weight:
                max_weight = weight
        return max_weight

    # For numbers with k digits
    for k in range(1, len(str(r)) + 1):
        if k == 1:
            # Single-digit case already handled
            continue

        # M = 10^k - 1 for k-digit numbers
        M = 10 ** k - 1

        # Find candidates near M/2 within [l, r]
        candidates = set()

        # Check numbers around M/2
        for m in range(max(1, l), min(r, M) + 1):
            if (M - m) >= l and (M - m) <= r:
                candidates.add(m)
                candidates.add(M - m)
                candidates.add(M//2)

        # Also check the boundaries
        candidates.add(l)
        candidates.add(r)
        candidates.add(M)
        candidates.add(10**(k-1) - 1)
        candidates.add(10**(k-1) - 2)
        candidates.add(10**(k-1))

        for n in candidates:
            if l <= n <= r:
