    for k in range(1, len(str(r)) + 1):
        # M = 10^k - 1 for k-digit numbers
        lower_k = 10 ** (k - 1)
        upper_k = 10 ** k - 1

        # Check if any k-digit numbers are in the range [l, r]
        start = max(l, lower_k)
        end = min(r, upper_k)

