def is_perfect_square(x):
    """Check if x is a perfect square."""
    s = int(x ** 0.5)
    return s * s == x


def solve():
    MOD = 10**9 + 7
    n = int(input())
    a = list(map(int, input().split()))

    # Check if product of two numbers is a perfect square
    def is_invalid_product(x, y):
        # Check if x*y is a perfect square
        prod = x * y
        if prod == 0:
            return False  # 0 is a perfect square but we don't have 0 in the array
        s = int(prod ** 0.5)
        return s * s == prod

    # Use DP: dp[mask][last] = number of ways to form a permutation ending with 'last'
    # where mask is a bitmask of used elements
    dp = {}  # Dictionary to store states

    # Initialize with single elements
    for i in range(n):
        mask = 1 << i
        dp[mask] = {i: 1}

    # Iterate through all masks
    for mask in range(1, 1 << n):
        # If we haven't computed this mask, skip
        if mask not in dp:
            continue

        # Get the last element(s) that can end a permutation with this mask
        for last, cnt in dp[mask].items():
            # Try to add an element that hasn't been used yet
            for i in range(n):
                if not (mask & (1 << i)):
                    # Check if product with last element is a perfect square
                    if not is_invalid_product(a[last], a[i]):
                        new_mask = mask | (1 << i)

                        # Update the new mask state
                        if new_mask not in dp:
                            dp[new_mask] = {}

                        # Add to the count
                        dp[new_mask][i] = (dp[new_mask].get(i, 0) + cnt) % MOD

    # Sum all permutations that use all n elements
    result = 0
    full_mask = (1 << n) - 1
    if full_mask in dp:
        result = sum(dp[full_mask].values()) % MOD

    print(result)

solve()
