def is_perfect_square(x):
    if x < 0:
        return False
    root = int(x**0.5)
    return root * root == x

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Count frequency of each number
    freq = defaultdict(int)
    for num in a:
        freq[num] += 1

    # Get distinct numbers
    distinct = list(freq.keys())
    k = len(distinct)

    # Precompute transitions: i -> j is valid if product not perfect square
    valid = [[True] * k for _ in range(k)]
    for i in range(k):
        for j in range(k):
            if i == j:
                continue
            prod = distinct[i] * distinct[j]
            valid[i][j] = not is_perfect_square(prod)

    # DP with mask and last number
    dp = [0] * (k * (1 << k))

    # For each mask and last number, store count
    for mask in range(1 << k):
        for last in range(k):
            if not (mask & (1 << last)):
                continue

            # Try adding each number that hasn't been used yet
            for new_last in range(k):
                if mask & (1 << new_last):
                    continue

                # Check if we can add new_last after last
                if not valid[last][new_last]:
                    continue

                # Count the number of ways to reach this state
                ways = dp[mask * k + last] * freq[distinct[new_last]]
                dp[mask * k + new_last] = (dp[mask * k + new_last] + ways) % MOD

    # Sum all states where mask has all bits set
    result = 0
    full_mask = (1 << k) - 1
    for last in range(k):
        result = (result + dp[full_mask * k + last]) % MOD

    print(result)

if __name__ == "__main__":
    solve()
