    valid = [[True] * k for _ in range(k)]
    for i in range(k):
        for j in range(k):
            if i == j:
                continue
            prod = distinct[i] * distinct[j]
            valid[i][j] = not is_perfect_square(prod)

    # Use DP with memoization and pruning
    memo = {}

    def dp(mask, last):
        if mask == (1 << k) - 1:
            return 1

        # Memoize
        key = (mask, last)
        if key in memo:
            return memo[key]

        result = 0

        # Try adding each number that hasn't been used yet
        for new_last in range(k):
            if not (mask & (1 << new_last)):
                # Check if we can add new_last after last
                if not valid[last][new_last]:
                    continue

                # Recursively add new_last
                count = freq[distinct[new_last]]
                result = (result + dp(mask | (1 << new_last), new_last) * count) % MOD

        memo[key] = result
        return result

    # Start with each number as the first element
    total = 0
    for first in range(k):
        total = (total + dp(1 << first, first) * freq[distinct[first]]) % MOD

