import sys

def is_valid(s):
    """Check if a substring is a valid bracket sequence."""
    # Count brackets
    balance = [0, 0]  # [parentheses balance, square brackets balance]
    for c in s:
        if c == '(':
            balance[0] += 1
        elif c == ')':
            balance[0] -= 1
        elif c == '[':
            balance[1] += 1
        elif c == ']':
            balance[1] -= 1

        # If either balance goes negative, it's invalid
        if balance[0] < 0 or balance[1] < 0:
