def solve():
    n, k = map(int, input().split())
    grid = [input().strip() for _ in range(n)]

    # dp[i][j] will store the lexicographically smallest string to reach (i,j)
    # and the cost (number of changes) to achieve it
    # We'll use a dictionary to store for each cell the best string for each possible cost
    dp = [[{} for _ in range(n)] for _ in range(n)]

    # Starting at (0,0)
    for cost in range(k+1):
        char = grid[0][0]
        if char == 'a':
            s = 'a'
        else:
            s = 'a' if cost > 0 else char
        dp[0][0][cost] = s

    # Iterate through the matrix
    for i in range(n):
        for j in range(n):
            # Get all possible states at this cell
            states = [(cost, s) for cost, s in dp[i][j].items()]

            # If we have reached this cell, propagate to neighbors
            for cost, s in states:
                # Move right if possible
                if j < n - 1:
                    next_char = grid[i][j+1]
                    next_cost = cost
                    next_str = s + next_char

                    # Option 1: keep next cell as is
                    if next_cost not in dp[i][j+1] or next_str < dp[i][j+1][next_cost]:
                        dp[i][j+1][next_cost] = next_str

                    # Option 2: change next cell to 'a'
                    if next_cost + 1 <= k:
                        next_str_alt = s + 'a'
                        if (next_cost + 1) not in dp[i][j+1] or next_str_alt < dp[i][j+1][next_cost + 1]:
                            dp[i][j+1][next_cost + 1] = next_str_alt

                # Move down if possible
                if i < n - 1:
                    next_char = grid[i+1][j]
                    next_cost = cost
                    next_str = s + next_char

                    # Option 1: keep next cell as is
                    if next_cost not in dp[i+1][j] or next_str < dp[i+1][j][next_cost]:
                        dp[i+1][j][next_cost] = next_str

                    # Option 2: change next cell to 'a'
                    if next_cost + 1 <= k:
                        next_str_alt = s + 'a'
                        if (next_cost + 1) not in dp[i+1][j] or next_str_alt < dp[i+1][j][next_cost + 1]:
                            dp[i+1][j][next_cost + 1] = next_str_alt

    # Find the lexicographically smallest string at (n-1, n-1)
    best_string = None
    for cost, s in dp[n-1][n-1].items():
        if best_string is None or s < best_string:
            best_string = s

    print(best_string)

solve()
