{"code": "
import sys

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    first_line = data[0].split()
    n, s = int(first_line[0]), int(first_line[1])
    sell_aggregated = {}
    buy_aggregated = {}

    for line in data[1:n+1]:
        parts = line.strip().split()
        if not parts:
            continue
        d, p, q = parts[0], int(parts[1]), int(parts[2])
        if d == 'S':
            sell_aggregated[p] = sell_aggregated.get(p, 0) + q
        else:
            buy_aggregated[p] = buy_aggregated.get(p, 0) + q

    # Process sells: best s (lowest prices)
    sells_sorted = sorted(sell_aggregated.items())  # sort by price ascending
    sells_selected = sells_sorted[:s]
    sells_output = [f"S {p} {v}" for p, v in sells_selected]
    # sort descending by price
    sells_output.sort(key=lambda x: int(x.split()[1]), reverse=True)

    # Process buys: best s (highest prices)
    buys_sorted = sorted(buy_aggregated.items(), key=lambda x: -x[0])  # sort descending by price
    buys_selected = buys_sorted[:s]
    buys_output = [f"B {p} {v}" for p, v in buys_selected]

    # Print
    for line in sells_output + buys_output:
        print(line)

if __name__ == "__main__":
    solve()
"}

